请对以下 case 进行三维加权评分。

=== case_id ===
Case-15-smart-home-001

=== 用户原始指令 (query.txt) ===
帮我弄个家居地图卡,带数字的话显示,点一下导航到家里,能看到连了几个设备

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我弄个家居地图卡,带数字的话显示,点一下导航到家里,能看到连了几个设备",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToIntent",
      "args": {
        "intentName": "StartNavigate",
        "params": {
          "dstLocation": {
            "latitude": "22.3193",
            "longitude": "114.1694"
          },
          "trafficpe": "Drive"
        }
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "home": {
        "name": {
          "type": "string",
          "description": "家庭位置名称，用于标识导航目的地。",
          "sampleValue": "家"
        },
        "connectedDeviceCount": {
          "type": "number",
          "description": "当前已连接的智能家居设备数量。",
          "sampleValue": 6
        },
        "deviceUnitText": {
          "type": "string",
          "description": "设备数量单位展示文本。",
          "sampleValue": "台设备"
        },
        "location": {
          "latitude": {
            "type": "string",
            "description": "家庭位置纬度，用于地图导航事件参数。",
            "sampleValue": "22.3193"
          },
          "longitude": {
            "type": "string",
            "description": "家庭位置经度，用于地图导航事件参数。",
            "sampleValue": "114.1694"
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/house_fill.svg",
      "description": "房屋实心图标，适合表达家庭位置、智能家居入口和回家导航。"
    }
  ]
}

